-- What a learner's dictionary prints around a definition and a general one
-- doesn't: how to build a sentence with the word (grammar codes, verb
-- patterns, its inflected forms), how common and how hard it is (frequency
-- band, CEFR), when it's appropriate (register and region labels), and the
-- mistakes learners make with it.
--
-- One row per English seed word, generated on first request by the `word`
-- function's GET /word/usage and shared by everyone after that, like
-- word_cache itself. Its own table rather than more word_cache columns: it's
-- generated by a separate call, later and lazily, so "not generated yet" is
-- simply "no row" — no checked_at flag needed.
create table if not exists word_usage (
  word          text primary key references word_cache (word) on delete cascade,
  cefr          text check (cefr in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')),
  frequency     smallint check (frequency between 1 and 3), -- 3 = core, 1 = rare
  syllables     text,                          -- "de·cide"
  labels        text[] not null default '{}',  -- formal, informal, US, UK…
  grammar       text[] not null default '{}',  -- countable, transitive…
  patterns      jsonb  not null default '[]',  -- [{ pattern, example }]
  forms         jsonb  not null default '[]',  -- [{ label, form }]
  variants      jsonb  not null default '[]',  -- [{ region, spelling }]
  mistakes      jsonb  not null default '[]',  -- [{ wrong, right, why }]
  confusables   jsonb  not null default '[]',  -- [{ word, difference }]
  synonym_notes jsonb  not null default '[]',  -- [{ word, difference }]
  phrasal_verbs jsonb  not null default '[]',  -- [{ phrase, meaning }]
  origin        text,
  created_at    timestamptz not null default now()
);

-- RLS on with no policies: only the service role touches it.
alter table word_usage enable row level security;
